// The plan before the brief 075 remap, and the kit catalogue the world and plan rule tests generate it with (brief 098, Splice; Sky 2026-11-08, "Do all").
// The old town has no tower sites, pier tower, gallery megastructure, megastructure bridges, service bays or SpaceHQ hall lanes, but their rules still hold, so
// about twenty rule tests keep their failing examples on that plan (briefs/075/remap/base.plan.json, committed), generated by today's code. They used to
// generate it with the live catalogue, so retiring a piece only that plan places moved them: rejecting Vela's eleven retired towers moved 25 tests (Vela's
// ripple run, 2026-11-07). They now generate it with the catalogue pinned here (tools/world/test/preremap.kit.json, its sha256 below): kit.json
// as it stood at 0f75f128, every piece that plan places adopted, its file lists emptied: only the copy and the importer read them (the generator reads ids,
// status, sizes, tags, the built tips and the poster sets: tools/world/gen/kitrefs.ts). A later kit change moves the live plan's tests, never these.
// One piece was added after the pin (brief 101): MastCamera_Lamp, the square's lamp mast. The plan reads the live civic block, whose lamp-terrace-w now carries
// the mast, and the zone pins name it, so without it the pre-remap zone took the old MastCamera and ZK-1 failed. It is the last row, its kit.json entry of 2026-11-09.
//   prePlan()      the plan, and the pinned catalogue for the rest of this test file (kitrefs pinKit; afterAll takes it off)
//   withPreKit(fn) fn on the pinned catalogue, for a file that also generates the live plan (which keeps the live catalogue)
//   preKit()       the pinned catalogue, for a test that looks up a piece the pre-remap world places
// usage: bun tools/world/test/preremap.ts --write <kit.json>   make the pin from a catalogue (then put the sha256 it prints below)
import { afterAll } from 'bun:test';
import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import type { Kit } from '../../../contracts/world/kit.schema';
import type { Plan } from '../../plan/plan';
import { pinKit, withKit } from '../gen/kitrefs';

const ROOT = resolve(import.meta.dir, '../../..');
export const PRE_REMAP_PLAN = 'briefs/075/remap/base.plan.json';
export const PRE_REMAP_KIT = resolve(import.meta.dir, 'preremap.kit.json');
/** The pin's own bytes: an edit to it fails here, not as a moved rule somewhere else. */
export const PRE_REMAP_KIT_SHA256 = 'bf6afe3681cd8122147ed74da429dc5630d675ae184f09eb04caed3b3b310304';
/** Where the pin came from (its `pin` field says the same). */
export const PRE_REMAP_KIT_FROM = { file: 'contracts/world/kit.json', commit: '0f75f128' } as const;

/** A catalogue with its file lists empty (`files: []` on every asset and section, no kit-wide `textures`), so it reads as a Kit wherever the generator takes one. */
export type PinnedKit = Kit & { pin: { from: string; commit: string; sha256: string; why: string } };

const sha = (b: string | Buffer) => createHash('sha256').update(b).digest('hex');
let checked = false;
/** The pin's path, its sha256 checked once. */
export function preKitFile(): string {
  if (!checked) {
    const got = sha(readFileSync(PRE_REMAP_KIT));
    if (got !== PRE_REMAP_KIT_SHA256) throw new Error(`${PRE_REMAP_KIT} is not the pinned catalogue (sha256 ${got.slice(0, 12)}, pinned ${PRE_REMAP_KIT_SHA256.slice(0, 12)}): remake it with --write, then update PRE_REMAP_KIT_SHA256 with the reason`);
    checked = true;
  }
  return PRE_REMAP_KIT;
}
let cache: PinnedKit | undefined;
export const preKit = (): PinnedKit => (cache ??= JSON.parse(readFileSync(preKitFile(), 'utf8')) as PinnedKit);
/** The pre-remap plan, and its kit pinned for the rest of the file that calls this (at its top level: bun runs a file's tests, then its afterAll, then the next file). */
export function prePlan(): Plan {
  pinKit(preKitFile());
  afterAll(() => pinKit(undefined));
  return JSON.parse(readFileSync(resolve(ROOT, PRE_REMAP_PLAN), 'utf8')) as Plan;
}
/** The plan alone, for a file that also generates the live plan: wrap what generates or judges it in withPreKit. */
export const prePlanOnly = (): Plan => JSON.parse(readFileSync(resolve(ROOT, PRE_REMAP_PLAN), 'utf8')) as Plan;
export const withPreKit = <T>(fn: () => T): T => withKit(preKitFile(), fn);

/** A catalogue as the pin keeps it: everything, its file lists empty (each asset's and each section's `files`; the kit-wide `textures` left out). */
export function kitPin(kitText: string, commit: string): string {
  const k = JSON.parse(kitText) as Kit & Record<string, unknown>, { textures: _t, assets, ...rest } = k;
  const sections = Object.fromEntries(Object.entries(rest).map(([key, v]) => [key, v && typeof v === 'object' && !Array.isArray(v) && 'files' in v ? { ...(v as Record<string, unknown>), files: [] } : v]));
  const pin = { from: PRE_REMAP_KIT_FROM.file, commit, sha256: sha(kitText), why: 'the catalogue the pre-remap plan is generated with in the rule tests (tools/world/test/preremap.ts); file lists emptied' };
  const head = Object.entries({ pin, ...sections }).map(([key, v]) => `${JSON.stringify(key)}: ${JSON.stringify(v)}`);
  return `{\n${head.join(',\n')},\n"assets": [\n${assets.map(a => JSON.stringify({ ...a, files: [] })).join(',\n')}\n]}\n`; // a row per asset, so a re-pin diffs by piece
}

if (import.meta.main) {
  const i = process.argv.indexOf('--write'), src = process.argv[i + 1];
  if (i < 0 || !src) { console.error('usage: bun tools/world/test/preremap.ts --write <kit.json> [--commit <sha>]'); process.exit(2); }
  const c = process.argv.indexOf('--commit'), text = kitPin(readFileSync(resolve(src), 'utf8'), c >= 0 ? process.argv[c + 1]! : PRE_REMAP_KIT_FROM.commit);
  writeFileSync(PRE_REMAP_KIT, text);
  console.log(`${PRE_REMAP_KIT}: ${JSON.parse(text).assets.length} assets, ${text.length} bytes, sha256 ${sha(text)}`);
}
